CREATE TABLE IF NOT EXISTS `crm_leads` (`id` int AUTO_INCREMENT PRIMARY KEY,`company` varchar(190) NOT NULL,`contact_name` varchar(190) NOT NULL,`email` varchar(190) NOT NULL,`phone` varchar(50) NOT NULL,`stage` varchar(32) NOT NULL DEFAULT 'new',`source` varchar(50) NOT NULL DEFAULT 'website',`owner` varchar(190) NOT NULL,`country` varchar(80) NOT NULL,`value` int NOT NULL DEFAULT 0,`next_action` varchar(190) NOT NULL,`next_action_at` timestamp NULL,`notes` text NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX `idx_crm_stage` (`stage`),INDEX `idx_crm_owner` (`owner`),INDEX `idx_crm_source` (`source`),INDEX `idx_crm_next_action` (`next_action_at`));
CREATE TABLE IF NOT EXISTS `crm_activities` (`id` int AUTO_INCREMENT PRIMARY KEY,`lead_id` int NOT NULL,`type` varchar(32) NOT NULL,`description` varchar(255) NOT NULL,`created_by` varchar(190) NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX `idx_crm_activity_lead` (`lead_id`),INDEX `idx_crm_activity_created` (`created_at`),CONSTRAINT `fk_crm_activity_lead` FOREIGN KEY (`lead_id`) REFERENCES `crm_leads` (`id`) ON DELETE CASCADE);
